function titleFromInterviewPrepSlug(slug) {
  var specialWords = {
    "ii": "II", "iii": "III", "iv": "IV", "v": "V", "vii": "VII",
    "xor": "XOR", "bst": "BST", "gcd": "GCD", "mk": "MK",
    "k": "K", "n": "N", "1d": "1D", "o1": "O(1)"
  };
  return slug.split("-").map(function (word) {
    if (specialWords[word]) return specialWords[word];
    if (/^\d/.test(word)) return word.replace(/^(\d+)([a-z])/, function (_, n, c) {
      return n + c.toUpperCase();
    });
    return word.charAt(0).toUpperCase() + word.slice(1);
  }).join(" ");
}

