(function addInterviewPrep621Questions() {
  var sectionsById = {};
  var existingSlugs = {};

  SHEET_SECTIONS.forEach(function (section) {
    sectionsById[section.id] = section;
    section.items.forEach(function (item) {
      var match = item[2] && item[2].match(/leetcode\.com\/problems\/([^/?#]+)/);
      if (match) existingSlugs[match[1]] = true;
    });
  });

  INTERVIEW_PREP_621_SLUGS.forEach(function (slug) {
    if (existingSlugs[slug]) return;
    var section = sectionsById[sectionForInterviewPrepSlug(slug)] || sectionsById.arrays;
    section.items.push([
      null,
      titleFromInterviewPrepSlug(slug),
      "https://leetcode.com/problems/" + slug + "/",
      null,
      false,
      ["IP621"]
    ]);
    existingSlugs[slug] = true;
  });
})();

