(function addCuratedSheetQuestions() {
  var sectionsById = {};
  var existingKeys = {};

  function curatedSheetKey(url) {
    var value = String(url || "").trim().toLowerCase()
      .replace(/[?#].*$/, "")
      .replace(/\/+$/, "");
    var match = value.match(/leetcode\.com\/problems\/([^/]+)/);
    if (match) return match[1];
    match = value.match(/(?:practice\.|www\.)?geeksforgeeks\.org\/problems\/([^/]+)/);
    if (match) return "gfg:" + match[1];
    return value
      .replace(/^https?:\/\/(?:www\.)?/, "")
      .replace(/^practice\./, "");
  }

  SHEET_SECTIONS.forEach(function (section) {
    sectionsById[section.id] = section;
    section.items.forEach(function (item) {
      existingKeys[curatedSheetKey(item[2])] = true;
    });
  });

  CURATED_SHEET_ADDITIONS.forEach(function (question) {
    var title = question[0];
    var url = question[1];
    var sectionId = question[2];
    var tags = question[3];
    var key = curatedSheetKey(url);
    if (existingKeys[key]) return;
    var section = sectionsById[sectionId] || sectionsById.arrays;
    section.items.push([null, title, url, null, false, tags]);
    existingKeys[key] = true;
  });
})();
